using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class RemainingFinish {
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/",E="Assets/Afrer_Seconds/05.Model/Environment/B5/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("Remaining_Domes_Art");string path=P+"RD_CompactToilet.fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.isReadable=true;mi.importAnimation=false;foreach(string n in new[]{"Steel","Coat"})mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"RD_"+n),AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/RD_"+n+".mat"));mi.SaveAndReimport();AssetDatabase.ImportAsset(E+"RD_C03_ProcessConnections.fbx",ImportAssetOptions.ForceSynchronousImport);var data=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/B5_RemainingDomes/plan.json"));int i=0;foreach(var p in data["placements"].Where(p=>(string)p["model"]=="RD_LivingAlcove").ToArray()){string room=(string)p["room"];var alcove=group.Find(room+"/"+(string)p["id"]);string name=room+"_Sanitary_Toilet_"+i++;if(group.Find(room+"/"+name))continue;var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),group.Find(room));g.name=name;g.transform.position=alcove.TransformPoint(new Vector3(.86f,0,1.12f));g.transform.rotation=alcove.rotation;foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;var pos=g.transform.localPosition;((JArray)data["placements"]).Add(new JObject{{"id",name},{"room",room},{"model","RD_CompactToilet"},{"position",new JArray(pos.x,pos.y,pos.z)},{"yaw",g.transform.localEulerAngles.y},{"collision",true}});}File.WriteAllText(repo+"/SourceAssets/B5_RemainingDomes/plan.json",data.ToString());Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{toilets=i,pipeConnections="actual equipment ports"};}
